//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.vScrenID = 'ULDSTF39203.xml';
scwin.isFilter = false;
scwin.v_schdl_adm_itm_tp_cd = "";
scwin.v_up_schdl_adm_itm_tp_nm = "";
scwin.v_up_schdl_adm_itm_tp_cd = "";
scwin.v_schdl_adm_itm_tp_cd = "";
scwin.v_ldMktTpCd = "";
scwin.allCnt = 0;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/*
 * 상위항목코드 조회
 */
scwin.fn_up_list = function() {
    var ldMktTpCd = rdo_MKT_ID.getValue();
    var url = "/DisclosureSchedule.do?method=listUpSchdlTpCd";
    url += "&LD_MKT_TP_CD=" + ldMktTpCd;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    MxDataSet_up_cd.DataID = encodeURI(url);
    MxDataSet_up_cd.reset();
};



/*
 * 서식검색
 */
scwin.fn_FormSearch = function() {
    //상장공시시장구분
    var mkt_tp_cd = rdo_mkt_tp_cd.getValue();
    //서식기관관리구분
    var inst_tp_cd = rdo_inst_tp_cd.getValue();
    //폐지서식여부
    var aliveCd = rdo_aliveCd.getValue();
    //서식구분
    var wrtrptMandocTpCd = rdo_wrtrptMaindocTpCd.getValue();
    //검색조건
    var searchGubun = $c.cp.valueOfIndex(cmb_searchGubun, "value", cmb_searchGubun.getSelectedIndex());
    //검색어
    var searchTxt = txt_searchTxt.getValue();

    //alert(mkt_tp_cd + "::" + inst_tp_cd + "::" + aliveCd + "::" + wrtrptMandocTpCd + "::" + searchGubun + "::" +  searchTxt);

    var url = "/DisclosureSchedule.do?method=listSearchForm";
    url += "&LD_MKT_TP_CD=" + mkt_tp_cd;
    url += "&FORM_ADM_INST_TP_CD=" + inst_tp_cd;
    url += "&ALIVE_CD=" + aliveCd;
    url += "&WRTRPT_MAINDOC_TP_CD=" + wrtrptMandocTpCd;
    url += "&SEARCH_GUBUN=" + searchGubun;
    url += "&SEARCH_TXT=" + searchTxt;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    MxDataSet_formList.DataID = encodeURI(url);
    MxDataSet_formList.reset();
};



/*
 * 저장 validation 체크
 */
scwin.fn_saveChk = function() {
    //상위일정관리항목유형코드
    if (txt_up_schdl_adm_itm_tp_nm.getValue() == "") {
        var msg = $c.stf.getMessageParam("MSG-A005", "상위일정관리유형코드");
        $c.win.alert(msg);
        txt_up_schdl_adm_itm_tp_nm.focus();
        return false;
    }
    //일정관리항목유형코드
    if (txt_schdl_adm_itm_tp_nm.getValue() == "") {
        var msg = $c.stf.getMessageParam("MSG-A005", "일정관리항목유형코드");
        $c.win.alert(msg);
        txt_schdl_adm_itm_tp_nm.focus();
        return false;
    }
    //관리항목
    if (txt_xpath.getValue() == "") {
        var msg = $c.stf.getMessageParam("MSG-A005", "관리항목 XPATH");
        $c.win.alert(msg);
        txt_xpath.focus();
        return false;
    }
    //일정계산기준구분코드
    if (rdo_schdl_calc_bas_tp_cd.getValue() == "") {
        var msg = $c.stf.getMessageParam("MSG-A005", "일정계산기준구분코드");
        $c.win.alert(msg);
        rdo_schdl_calc_bas_tp_cd.focus();
        return false;
    }
    //공시일정관리기준구분코드
    if (rdo_discls_schdl_adm_bas_tp_cd.getValue() == "") {
        var msg = $c.stf.getMessageParam("MSG-A005", "공시일정관리기준구분코드");
        $c.win.alert(msg);
        rdo_discls_schdl_adm_bas_tp_cd.focus();
        return false;
    }
    //공시일정등급코드
    //if (rdo_discls_schdl_grd_cd.CodeValue == "") {
    //	var msg = getMessageParam("MSG-A005", "공시일정등급코드");
    //	alert(msg);rdo_discls_schdl_grd_cd.focus();return false;
    //}

    //자동계산여부
    if (rdo_auto_calc_yn.getValue() == "") {
        var msg = $c.stf.getMessageParam("MSG-A005", "자동계산여부");
        $c.win.alert(msg);
        rdo_auto_calc_yn.focus();
        return false;
    }
    //제출시스템사용여부
    if (rdo_submit_sys_use_yn.getValue() == "") {
        var msg = $c.stf.getMessageParam("MSG-A005", "제출시스템사용여부");
        $c.win.alert(msg);
        rdo_submit_sys_use_yn.focus();
        return false;
    }
    //계산년수
    if (txt_calc_yys.getValue() == "") {
        var msg = $c.stf.getMessageParam("MSG-A005", "계산년수");
        $c.win.alert(msg);
        txt_calc_yys.focus();
        return false;
    }
    //계산월수
    if (txt_calc_mms.getValue() == "") {
        var msg = $c.stf.getMessageParam("MSG-A005", "계산월수");
        $c.win.alert(msg);
        txt_calc_mms.focus();
        return false;
    }
    //계산일수
    if (txt_calc_dys.getValue() == "") {
        var msg = $c.stf.getMessageParam("MSG-A005", "계산일수");
        $c.win.alert(msg);
        txt_calc_dys.focus();
        return false;
    }
    //보정일수
    if (txt_corrct_dys.getValue() == "") {
        var msg = $c.stf.getMessageParam("MSG-A005", "보정일수");
        $c.win.alert(msg);
        txt_corrct_dys.focus();
        return false;
    }
    //시장휴무보정일수
    if (txt_mkt_holdy_corrct_dys.getValue() == "") {
        var msg = $c.stf.getMessageParam("MSG-A005", "시장휴무보정일수");
        $c.win.alert(msg);
        txt_mkt_holdy_corrct_dys.focus();
        return false;
    }
    return true;
};

/*
 * 저장
 */
scwin.fn_save = function() {
    MxDataSet.setCellData(1, "LD_MKT_TP_CD", rdo_MKT_ID.getValue());
    MxDataSet.setCellData(1, "SCHDL_ADM_ITM_TP_CD", txt_schdl_adm_itm_tp_cd.getValue());
    MxLogicalTr.Action = "/DisclosureSchedule.do?method=saveDischdlCalfac";
    MxLogicalTr.KeyName = "toinb_dataid4";
    MxLogicalTr.KeyValue = "JSP(I:pInputMaster=MxDataSet)";
    MxLogicalTr.Post();
    MxDataSet.removeAll();
    MxDataSet.insertRow();
    scwin.fn_txtInit();
};


/*
 * 등록정보 텍스트 정보 초기화
 */
scwin.fn_txtInit = function() {
    txt_up_schdl_adm_itm_tp_nm.setValue("");
    txt_schdl_adm_itm_tp_nm.setValue("");
    txt_formKorNm.setValue("");
    txt_schdl_search.setValue("");
    txt_searchTxt.setValue("");
    cmb_searchGubun.setSelectedIndex(0);
};


/*
 * 일정관리항목유형코드 검색
 */
scwin.fn_SearchSchdl = function(row) {
    var schdl_adm_itm_tp_cd = MxDataSet_up_cd.getCellData(row, "SCHDL_ADM_ITM_TP_CD");
    var cd_nm = MxDataSet_up_cd.getCellData(row, "CD_NM");
    txt_up_schdl_adm_itm_tp_nm.setValue(cd_nm);
    txt_up_schdl_adm_itm_tp_cd.setValue(schdl_adm_itm_tp_cd);

    //일정관리항목유형코드 초기화
    txt_schdl_adm_itm_tp_nm.setValue("");
    txt_schdl_adm_itm_tp_cd.setValue("");
    var ldMktTpCd = rdo_MKT_ID.getValue();
    var url = "/DisclosureSchedule.do?method=listSchdlTpCd";
    url += "&LD_MKT_TP_CD=" + ldMktTpCd;
    url += "&UP_SCHDL_ADM_ITM_TP_CD=" + schdl_adm_itm_tp_cd;
    url += "&SCHDL_ADM_ITM_TP_CD=";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    MxDataSet_schdl_tp_cd.DataID = encodeURI(url);
    MxDataSet_schdl_tp_cd.reset();
    MxDataSet_schdl_tp_cd.UseFilter = "false";
    MxDataSet_schdl_tp_cd.Filter();
};


/*
 * 저장후 일정관리항목유형코드 재검색
 */
scwin.fn_ReSearch = function(v_cdNm) {
    scwin.fn_SearchSchdl(MxDataSet_up_cd.getRowPosition());
    txt_schdl_search.setValue(v_cdNm);
    txt_schdl_search.style.display = "";
    scwin.allCnt = 0;
    scwin.v_schdl_adm_itm_tp_cd = txt_schdl_search.getValue();
    if (!MxDataSet_schdl_tp_cd.UseFilter) MxDataSet_schdl_tp_cd.UseFilter = "true";
    MxDataSet_schdl_tp_cd.Filter();
};
scwin.isNumber = function(inputVal) {
    oneDecimal = false;
    var inputStr = inputVal.toString();
    var oneChar;
    for (var i = 0; i < inputStr.length; i++) {
        oneChar = inputStr.charAt(i);
        if (i == 0 && oneChar == "-") {
            continue;
        }
        if (oneChar == "." && !oneDecimal) {
            oneDecimal = true;
            continue;
        }
        if (oneChar < "0" || oneChar > "9") {
            return false;
        }
    }
    return true;
};
scwin.gform_onload = function() {
    MxDataSet_up_cd.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=ADM_ITM_TP_CD"; //상위일정관리항목유형코드
    MxDataSet_up_cd.reset();
    MxDataSet.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BYFOM_DISCHDL_CALFAC"; //입력용 dataset
    MxDataSet.reset();
    rdo_mkt_tp_cd.setValue(" ");
    rdo_inst_tp_cd.setValue(" ");
    rdo_aliveCd.setValue(" ");
    rdo_wrtrptMaindocTpCd.setValue(" ");
    txt_up_schdl_adm_itm_tp_cd.style.display = "none";
    txt_schdl_adm_itm_tp_cd.style.display = "none";
    txt_schdl_search.style.display = "none";
    rdo_mkt_tp_cd.setValue(1);
    scwin.fn_up_list();
    scwin.fn_txtInit();
};
scwin.MxDataSet_up_cd_OnLoadCompleted = function(rowcount) {
    //alert('MxDataSet_up_cd.OnLoadCompleted('+rowcount+')');
    scwin.fn_SearchSchdl(1);
};
scwin.MxDataSet_up_cd_OnLoadError = function() {
    $c.stf.alert_error(MxDataSet_up_cd);
};
scwin.rdo_MKT_ID_OnSelChange = function() {
    MxDataSet_schdl_tp_cd.removeAll();
    scwin.fn_up_list();
    rdo_mkt_tp_cd.setValue(rdo_MKT_ID.getValue());
};
scwin.MxGrid_2_OnDblClick = function(row, colid) {
    //alert('MxGrid_2.OnDblClick('+row+','+ colid+')');
    txt_form_cd.setValue(MxDataSet_formList.getCellData(row, "FORM_CD"));
    txt_form_ver.setValue(MxDataSet_formList.getCellData(row, "FORM_VER"));
    var formVer = txt_form_ver.getValue();
    if (formVer.length < 4) {
        txt_form_ver.setValue(txt_form_ver.getValue() + "0");
    }
    txt_formKorNm.setValue(MxDataSet_formList.getCellData(row, "FORM_KOR_NM"));
};
scwin.MxDataSet_OnLoadCompleted = function(rowcount) {
    MxDataSet.insertRow();
};
scwin.MxDataSet_OnFilter = function(row) {
    //if(MxDataSet.NameString(row,"EMP_NM") .indexOf(schName)!=-1 || (schName=="%")){

    //	allCnt++;		

    //	isFilter = true;

    //}else{		

    //	isFilter = false;

    //}

    //if(row == 1 || row== -1) countAllRow();

    //return isFilter;

};
scwin.MxLogicalTr_OnSuccess = function() {
    $c.win.alert('저장이 완료되었습니다.');
    scwin.fn_txtInit();
    scwin.fn_up_list();
};
scwin.MxLogicalTr_OnFail = function() {
    $c.win.alert('저장에 실패했습니다.');
};
scwin.MxDataSet_schdl_tp_cd_OnFilter = function(row) {
    if (MxDataSet_schdl_tp_cd.getCellData(row, "CD_NM").indexOf(scwin.v_schdl_adm_itm_tp_cd) != -1 || (scwin.v_schdl_adm_itm_tp_cd == "%")) {
        scwin.allCnt++;
        scwin.isFilter = true;
    } else {
        scwin.isFilter = false;
    }
    //if(row == 1 || row== -1) countAllRow();
    return scwin.isFilter;
};
scwin.txt_schdl_search_onkeydown = function() {
    if (window.event.keyCode == 13) {
        //if (txt_schdl_search.value == "") alert("일정관리항목유형코드를 입력해주세요.");

        scwin.allCnt = 0;
        scwin.v_schdl_adm_itm_tp_cd = txt_schdl_search.getValue();
        if (!MxDataSet_schdl_tp_cd.UseFilter) MxDataSet_schdl_tp_cd.UseFilter = "true";
        MxDataSet_schdl_tp_cd.Filter();
    }
};
scwin.img_xpath_onclick = async function() {
    if (txt_form_cd.getValue() == "") {
        var msg = $c.stf.getMessageParam("MSG-A005", "서식코드");
        $c.win.alert(msg);
        txt_searchTxt.focus();
        return false;
    }
    await $c.frame.CreateDialogFrame("virWinSave", g_real_manager_url + "/filing/findForm.do?method=viewFormForm&formCd=" + txt_form_cd.getValue() + "&formVer=" + txt_form_ver.getValue(), "서식정보", 120, 120, 1275, 785, "tool");
};
scwin.MxGrid_1_OnClick = function(row, colid) {
    txt_schdl_adm_itm_tp_cd.setValue(MxDataSet_schdl_tp_cd.getCellData(row, "SCHDL_ADM_ITM_TP_CD"));
    txt_schdl_adm_itm_tp_nm.setValue(MxDataSet_schdl_tp_cd.getCellData(row, "CD_NM"));
};
scwin.MxGrid_1_OnKeyUp = function(row, colid, data) {
    if (data == "13") {
        txt_schdl_search.style.display = "";
        txt_schdl_search.focus();
    }
};
scwin.grd_uplist_OnClick = function(row, colid) {
    scwin.fn_SearchSchdl(row);
};
scwin.rdo_mkt_tp_cd_OnSelChange = function() {
    //alert(rdo_mkt_tp_cd.CodeValue);

};
scwin.txt_searchTxt_onkeyup = function() {
    if (window.event.keyCode == 13) {
        scwin.fn_FormSearch();
    }
};
scwin.btn_save_onclick = function() {
    if (!scwin.fn_saveChk()) {
        return;
    }
    if (!confirm("저장하시겠습니까?")) {
        return;
    }
    scwin.fn_save();
};
scwin.img_formSearch_onclick = function() {
    scwin.fn_FormSearch();
};
scwin.image_12_onclick = async function() {
    //상위코드
    scwin.v_up_schdl_adm_itm_tp_cd = MxDataSet_up_cd.getCellData(MxDataSet_up_cd.getRowPosition(), "SCHDL_ADM_ITM_TP_CD");
    scwin.v_up_schdl_adm_itm_tp_nm = MxDataSet_up_cd.getCellData(MxDataSet_up_cd.getRowPosition(), "CD_NM");
    scwin.v_ldMktTpCd = rdo_MKT_ID.getValue();
    await $c.frame.CreateDialogFrame("gform", "/dsclmgt/ULDSTF39204.gfm", "일정관리항목유형코드 신규등록", 300, 100, 520, 250, "window");
};
scwin.MxDataSet_formList_OnLoadError = function() {
    $c.stf.alert_error(MxDataSet_formList);
};
scwin.MxDataSet_schdl_tp_cd_OnLoadCompleted = function(rowcount) {
    if (rowcount > 0) {
        txt_schdl_adm_itm_tp_nm.setValue(MxDataSet_schdl_tp_cd.getCellData(1, "CD_NM"));
        txt_schdl_adm_itm_tp_cd.setValue(MxDataSet_schdl_tp_cd.getCellData(1, "SCHDL_ADM_ITM_TP_CD"));
        txt_searchTxt.focus();
    }
};
scwin.txt_xpath_onkeyup = function() {
    if (txt_form_cd.getValue() != "") {
        var form_cd = txt_form_cd.getValue();
        if (!$c.cm.isNumber(FORM_CD.substr(0, 1))) {
            $c.win.alert("지정된 서식이 단위 서식입니다. 서식코드를 확인해주세요.");
        }
    }
};
scwin.MxGrid_1_OnLButtonDblClk = async function(row, colid, xpos, ypos) {
    scwin.v_schdl_adm_itm_tp_cd = MxDataSet_schdl_tp_cd.getCellData(row, "SCHDL_ADM_ITM_TP_CD");
    scwin.v_ldMktTpCd = rdo_MKT_ID.getValue();
    await $c.frame.CreateDialogFrame("gform", "/dsclmgt/ULDSTF39205.gfm", "타시장 일정관리항목유형코드", 300, 100, 500, 340, "window");
};
